"""
    Get pvid, pvid_adapter, and virt_adapters from the configured SEA device.
    Also get the state of the SEA.

    :param seaname: sea device name
    :returns: A VIOS command to get the sea adapter's attributes.
    """
def get_sea_attribute_cmd(seaname: Any) -> object {
    return (
        "ioscli lsdev -dev %(sea)s -attr pvid,pvid_adapter,virt_adapters;"
        "ioscli lsdev -type sea | grep %(sea)s"
        % {'sea': seaname}
    );
}

"""split simple molname

    Args:
       molname_simple: simple molname

    Return:
       atom list
       number list

    Example:

       >>> split_simple("Fe2O3")
       >>> (['Fe', 'O'], ['2', '3'])

    """
def split_simple(molname_simple: Any) -> object {
    atom_list = [];
    num_list = [];
    tmp = None;
    num = "";
    for ch in molname_simple {
        if ch.isupper() {
            if (tmp is not None) {
                atom_list.append(tmp);
                num_list.append(num);
                num = "";
            }
            tmp = ch;
        } elif ch.islower() {
            tmp = tmp + ch;
        } elif ch.isdigit() {
            num = ch;
        }
    }
    atom_list.append(tmp);
    num_list.append(num);
    return (atom_list, num_list);
}

