"""
    Given an index and list of sizes, return a
    name for the layer.

    >>> autoname(0, sizes=4)
    'input'
    >>> autoname(1, sizes=4)
    'hidden1'
    >>> autoname(2, sizes=4)
    'hidden2'
    >>> autoname(3, sizes=4)
    'output'
    """
def autoname(index: Any, sizes: Any) -> object {
    if (index == 0) {
        n = "input";
    } elif (index == (sizes - 1)) {
        n = "output";
    } elif (sizes == 3) {
        n = "hidden";
    } else {
        n = "hidden%d" % index;
    }
    return n;
}

"""
    Normalize the value of all element in a collection
    each element will be divided by the sum
    """
def normalize(collection: Any) -> object {
    if isinstance(collection, `dict) {
        total = 0;
        result = {};
        for key in collection {
            total += collection[key];
        }
        if (total == 0) {
            return {};
        }
        for key in collection {
            result[key] = collection[key] / total;
        }
    } else {
        total = sum(collection);
        result = [0] * len(collection);
        if (total == 0) {
            return result;
        }
        for i in range(len(collection)) {
            result[i] = collection[i] / total;
        }
    }
    return result;
}

